spec.setup_code:
var P = 14;
var INK = '#04204B', SEC = '#3D5F91', GUIDE = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F', TEAL = '#138374', VIO = '#6A47C2';
var COLS = [WARM, TEAL, VIO];
var CAPS = [
  'Rectified-flow path: xₜ = (1 − t) x₀ + t ε',
  'ε-prediction (DDPM, SD 1): where did the noise come from?',
  'x̂₀-prediction (AlphaFold 3, EDM): where is the data?',
  'velocity v = ε − x₀ (SD3, FLUX): which way along the path?',
  'given xₜ and t, any one determines the other two'
];
var EQS = [
  '',
  'ε = (xₜ − (1 − t) x₀) / t',
  'x₀ = (xₜ − t ε) / (1 − t)',
  'v = ε − x₀ = (ε − xₜ) / (1 − t)',
  'x₀ = xₜ − t v     ε = xₜ + (1 − t) v'
];
var EQC = [INK, WARM, TEAL, VIO, INK];
var BOUNDS = [0, 2, 5, 8, 11, 14];

function sm(x) { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); }

function arrowAlpha(i, T) {
  var s = 2 + 3 * i, e = s + 3, a;
  if (T < s) a = 0;
  else if (T < e) a = sm((T - s) / 0.6);
  else if (T < 11) a = 1 - 0.7 * sm((T - e) / 0.6);
  else a = (i === 2) ? 1 : 0.3 + 0.7 * sm((T - 11) / 0.6);
  return a * (1 - sm((T - 13.5) / 0.5));
}

function wrapLines(ctx, str, maxW) {
  if (ctx.measureText(str).width <= maxW) return [str];
  var w = str.split(' '), best = [str], bestM = 1e9;
  for (var k = 1; k < w.length; k++) {
    var a = w.slice(0, k).join(' '), b = w.slice(k).join(' ');
    var m = Math.max(ctx.measureText(a).width, ctx.measureText(b).width);
    if (m < bestM) { bestM = m; best = [a, b]; }
  }
  return best;
}

function arrow(ctx, x1, y1, x2, y2, col, alpha, lw) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx * dx + dy * dy);
  if (len < 5 || alpha < 0.01) return;
  var ux = dx / len, uy = dy / len;
  var hs = Math.min(10, len * 0.6);
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2 - ux * hs * 0.7, y2 - uy * hs * 0.7); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - ux * hs + uy * hs * 0.5, y2 - uy * hs - ux * hs * 0.5);
  ctx.lineTo(x2 - ux * hs - uy * hs * 0.5, y2 - uy * hs + ux * hs * 0.5);
  ctx.closePath(); ctx.fill();
  ctx.globalAlpha = 1;
}

function dot(ctx, x, y, r, fill, stroke) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = fill; ctx.fill();
  ctx.lineWidth = 1.5; ctx.strokeStyle = stroke; ctx.stroke();
}

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  var T = time % P;
  var t = 0.5 - 0.35 * Math.cos(2 * Math.PI * T / P);

  var ph = 0;
  for (var k = 0; k < 5; k++) { if (T >= BOUNDS[k]) ph = k; }
  var lt = T - BOUNDS[ph], dur = BOUNDS[ph + 1] - BOUNDS[ph];
  var ca = Math.min(sm(lt / 0.35), sm((dur - lt) / 0.35));
  if (ph === 4) ca = Math.min(ca, 1 - sm((T - 13.6) / 0.4));

  // geometry
  var p0x = width * 0.15, p0y = height * 0.44;
  var p1x = width * 0.85, p1y = height * 0.34;
  var dx = p1x - p0x, dy = p1y - p0y, L = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var xx = p0x + dx * t, xy = p0y + dy * t;

  // caption
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 12px sans-serif';
  var cl = wrapLines(ctx, CAPS[ph], width - 24);
  ctx.globalAlpha = ca; ctx.fillStyle = (ph >= 1 && ph <= 3) ? COLS[ph - 1] : INK;
  for (var q = 0; q < cl.length; q++) ctx.fillText(cl[q], width / 2, 18 + q * 16);
  ctx.globalAlpha = 1;

  // path line
  ctx.strokeStyle = GUIDE; ctx.lineWidth = 1.5; ctx.setLineDash([5, 4]);
  ctx.beginPath(); ctx.moveTo(p0x, p0y); ctx.lineTo(p1x, p1y); ctx.stroke();
  ctx.setLineDash([]);

  // arrows
  var al = [arrowAlpha(0, T), arrowAlpha(1, T), arrowAlpha(2, T)];
  var vc = [xx + nx * 46, xy + ny * 46];
  var vh = 0.13 * L;
  // v arrow with dashed connector
  if (al[2] > 0.01) {
    ctx.globalAlpha = al[2] * 0.6; ctx.strokeStyle = VIO; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
    ctx.beginPath(); ctx.moveTo(xx + nx * 7, xy + ny * 7); ctx.lineTo(vc[0], vc[1]); ctx.stroke();
    ctx.setLineDash([]); ctx.globalAlpha = 1;
    arrow(ctx, vc[0] - ux * vh, vc[1] - uy * vh, vc[0] + ux * vh, vc[1] + uy * vh, VIO, al[2], 1.8 + 2 * al[2]);
  }
  arrow(ctx, xx + ux * 9, xy + uy * 9, p1x - ux * 13, p1y - uy * 13, WARM, al[0], 1.8 + 2 * al[0]);
  arrow(ctx, xx - ux * 9, xy - uy * 9, p0x + ux * 13, p0y + uy * 13, TEAL, al[1], 1.8 + 2 * al[1]);

  // arrow labels
  ctx.font = 'bold 12px sans-serif';
  if (al[0] > 0.01) {
    var mx = (xx + p1x) / 2, my = (xy + p1y) / 2;
    ctx.globalAlpha = al[0]; ctx.fillStyle = WARM; ctx.fillText('ε̂', mx + nx * 15, my + ny * 15);
  }
  if (al[1] > 0.01) {
    var mx2 = (xx + p0x) / 2, my2 = (xy + p0y) / 2;
    ctx.globalAlpha = al[1]; ctx.fillStyle = TEAL; ctx.fillText('x̂₀', mx2 + nx * 15, my2 + ny * 15);
  }
  if (al[2] > 0.01) {
    ctx.globalAlpha = al[2]; ctx.fillStyle = VIO; ctx.fillText('v', vc[0] + nx * 15, vc[1] + ny * 15);
  }
  ctx.globalAlpha = 1;

  // highlight rings on the target
  var pulse = 10 + 3 * Math.sin(time * 5);
  if (ph === 1) {
    ctx.globalAlpha = al[0]; ctx.strokeStyle = WARM; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(p1x, p1y, pulse, 0, Math.PI * 2); ctx.stroke();
  } else if (ph === 2) {
    ctx.globalAlpha = al[1]; ctx.strokeStyle = TEAL; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(p0x, p0y, pulse, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // points
  dot(ctx, p0x, p0y, 7, BLUE, BLUE);
  dot(ctx, p1x, p1y, 7, GUIDE, SEC);
  dot(ctx, xx, xy, 6, INK, '#ffffff');
  ctx.font = '12px sans-serif';
  ctx.fillStyle = BLUE; ctx.fillText('x₀ data', p0x, p0y - 22);
  ctx.fillStyle = SEC; ctx.fillText('ε noise', p1x, p1y - 22);
  ctx.fillStyle = INK; ctx.fillText('xₜ', xx + nx * -20, xy + ny * -20);

  // path formula (always) and phase equation
  ctx.font = '12px sans-serif'; ctx.fillStyle = SEC;
  ctx.fillText('xₜ = (1 − t) x₀ + t ε', width / 2, height * 0.66);
  if (EQS[ph] !== '') {
    ctx.font = 'bold 13px sans-serif';
    ctx.globalAlpha = ca; ctx.fillStyle = EQC[ph];
    ctx.fillText(EQS[ph], width / 2, height * 0.73);
    ctx.globalAlpha = 1;
  }

  // t slider
  var sw = Math.min(240, width - 90), sx0 = (width - sw) / 2, sy = height * 0.89;
  ctx.font = '12px sans-serif'; ctx.fillStyle = INK;
  ctx.fillText('t = ' + t.toFixed(2), width / 2, height * 0.82);
  ctx.strokeStyle = GUIDE; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(sx0, sy); ctx.lineTo(sx0 + sw, sy); ctx.stroke();
  ctx.strokeStyle = SEC; ctx.lineWidth = 1;
  var tk = [0.15, 0.85];
  for (var j = 0; j < 2; j++) {
    ctx.beginPath(); ctx.moveTo(sx0 + sw * tk[j], sy - 6); ctx.lineTo(sx0 + sw * tk[j], sy + 6); ctx.stroke();
  }
  dot(ctx, sx0 + sw * t, sy, 7, BLUE, '#ffffff');
  ctx.fillStyle = SEC;
  ctx.fillText('0 (data)', sx0 + 4, sy + 20);
  ctx.fillText('1 (noise)', sx0 + sw - 4, sy + 20);
  ctx.textAlign = 'left';
}

return { draw: draw };
